package ir.codelighthouse.bazikhooneh.account;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.Build;import ir.codelighthouse.bazikhooneh.*;import org.json.*;
public final class NotificationSync{private static final String CHANNEL="social";private NotificationSync(){}
 public static void refresh(Activity activity){if(Build.VERSION.SDK_INT>=33&&activity.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){activity.requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},41);return;}refreshBackground(activity);}
 public static void refreshBackground(Context context){SessionStore store=new SessionStore(context);android.content.SharedPreferences settings=context.getSharedPreferences(SettingsActivity.PREFS,Context.MODE_PRIVATE);if(!store.isSignedIn()||!settings.getBoolean(SettingsActivity.NOTIFICATIONS,true))return;new AccountManagementClient(BuildConfig.API_BASE_URL,store.token(),new AccountManagementClient.Listener(){public void onSuccess(String op,JSONObject json){showNewest(context,json);}public void onError(String error){}}).get("notifications","/api/v1/accounts/notifications/");}
 private static void showNewest(Context context,JSONObject json){JSONArray values=json.optJSONArray("results");if(values==null)return;android.content.SharedPreferences state=context.getSharedPreferences("notification_state",Context.MODE_PRIVATE),settings=context.getSharedPreferences(SettingsActivity.PREFS,Context.MODE_PRIVATE);long last=state.getLong("last_id",0),newest=last;for(int i=values.length()-1;i>=0;i--){JSONObject item=values.optJSONObject(i);long id=item.optLong("id");newest=Math.max(newest,id);if(id<=last)continue;String kind=item.optString("kind");boolean allowed="friend_request".equals(kind)?settings.getBoolean(SettingsActivity.FRIEND_NOTIFICATIONS,true):settings.getBoolean(SettingsActivity.GAME_NOTIFICATIONS,true);if(allowed)show(context,item,id);}state.edit().putLong("last_id",newest).apply();}
 private static void show(Context context,JSONObject item,long id){NotificationManager manager=(NotificationManager)context.getSystemService(Context.NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)manager.createNotificationChannel(new NotificationChannel(CHANNEL,context.getString(R.string.notifications_title),NotificationManager.IMPORTANCE_DEFAULT));String kind=item.optString("kind");JSONObject data=item.optJSONObject("data");Class<?> destination=("friend_request".equals(kind)||"game_invite".equals(kind))?FriendsActivity.class:NotificationsActivity.class;if(data!=null&&data.has("room_code")&&kind.startsWith("room_"))destination=CommunityRoomActivity.class;Intent intent=new Intent(context,destination);if(data!=null&&data.has("room_code"))intent.putExtra("room_code",data.optString("room_code"));PendingIntent target=PendingIntent.getActivity(context,(int)(id%Integer.MAX_VALUE),intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder builder=Build.VERSION.SDK_INT>=26?new Notification.Builder(context,CHANNEL):new Notification.Builder(context);manager.notify((int)(id%Integer.MAX_VALUE),builder.setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle(item.optString("title")).setContentText(item.optString("body")).setContentIntent(target).setAutoCancel(true).build());}
}
